(function () {
  'use strict';

  var STORAGE_KEY = 'todomvc-shakedown';
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var mainSection = document.querySelector('.main');
  var footerSection = document.querySelector('.footer');
  var todoCount = document.querySelector('.todo-count');
  var toggleAllCheckbox = document.querySelector('.toggle-all');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filterLinks = document.querySelectorAll('.filters a');

  function loadTodos() {
    try {
      return JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      return [];
    }
  }

  function saveTodos(todos) {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2);
  }

  function getFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  /** @planks("the new todo input is focused") @planks("the counter shows {string}") @planks("the {string} section is hidden") @planks("the {string} section is visible") */
  function render() {
    var todos = loadTodos();
    var filter = getFilter();
    todoList.innerHTML = '';

    var filtered = todos.filter(function (todo) {
      if (filter === 'active') return !todo.completed;
      if (filter === 'completed') return todo.completed;
      return true;
    });

    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      var div = document.createElement('div');
      div.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      div.appendChild(checkbox);
      div.appendChild(label);
      div.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(div);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });

    var activeCount = todos.filter(function (t) { return !t.completed; }).length;
    var completedCount = todos.filter(function (t) { return t.completed; }).length;
    var totalCount = todos.length;

    todoCount.innerHTML = '<strong>' + activeCount + '</strong> ' +
      (activeCount === 1 ? 'item left' : 'items left');

    if (totalCount === 0) {
      mainSection.style.display = 'none';
      footerSection.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footerSection.style.display = '';
    }

    toggleAllCheckbox.checked = totalCount > 0 && activeCount === 0;
    clearCompletedBtn.style.display = completedCount > 0 ? '' : 'none';

    filterLinks.forEach(function (link) {
      link.classList.remove('selected');
      var linkFilter = link.getAttribute('href');
      if (linkFilter === '#/' && filter === 'all') link.classList.add('selected');
      if (linkFilter === '#/active' && filter === 'active') link.classList.add('selected');
      if (linkFilter === '#/completed' && filter === 'completed') link.classList.add('completed');
      if (linkFilter === '#/active' && filter === 'active') link.classList.add('selected');
    });

    newTodoInput.focus();
  }

  /** @planks("I add a todo {string}") */
  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    var todos = loadTodos();
    todos.push({ id: generateId(), title: trimmed, completed: false });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the checkbox for todo {string}") */
  function toggleTodo(id) {
    var todos = loadTodos();
    todos = todos.map(function (t) {
      if (t.id === id) return { id: t.id, title: t.title, completed: !t.completed };
      return t;
    });
    saveTodos(todos);
    render();
  }

  /** @planks("I check the toggle-all checkbox") */
  function toggleAll() {
    var todos = loadTodos();
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos = todos.map(function (t) {
      return { id: t.id, title: t.title, completed: !allCompleted };
    });
    saveTodos(todos);
    render();
  }

  /** @planks("I click the clear completed button") */
  function clearCompleted() {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return !t.completed; });
    saveTodos(todos);
    render();
  }

  /** @planks("the destroy button for todo {string} is visible") */
  function destroyTodo(id) {
    var todos = loadTodos();
    todos = todos.filter(function (t) { return t.id !== id; });
    saveTodos(todos);
    render();
  }

  /** @planks("Editing saves on Enter") @planks("Editing saves on blur") @planks("Edit input is trimmed") */
  function saveEdit(id, newTitle) {
    var trimmed = newTitle.trim();
    var todos = loadTodos();
    if (!trimmed) {
      todos = todos.filter(function (t) { return t.id !== id; });
    } else {
      todos = todos.map(function (t) {
        if (t.id === id) return { id: t.id, title: trimmed, completed: t.completed };
        return t;
      });
    }
    saveTodos(todos);
    render();
  }

  /** @planks("Escape cancels edit") */
  function cancelEdit(li) {
    li.classList.remove('editing');
    var editInput = li.querySelector('.edit');
    var todoId = li.dataset.id;
    var todos = loadTodos();
    var todo = todos.find(function (t) { return t.id === todoId; });
    if (todo) editInput.value = todo.title;
  }

  // Event: new todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Events: todo list (delegated)
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = li.dataset.id;

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  todoList.addEventListener('dblclick', function (e) {
    if (e.target.tagName === 'LABEL') {
      var li = e.target.closest('li');
      li.classList.add('editing');
      var editInput = li.querySelector('.edit');
      editInput.focus();
    }
  });

  todoList.addEventListener('keydown', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      var id = li.dataset.id;
      if (e.key === 'Enter') {
        saveEdit(id, e.target.value);
      } else if (e.key === 'Escape') {
        cancelEdit(li);
      }
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (e.target.classList.contains('edit')) {
      var li = e.target.closest('li');
      if (li && li.classList.contains('editing')) {
        saveEdit(li.dataset.id, e.target.value);
      }
    }
  }, true);

  // Event: toggle all
  toggleAllCheckbox.addEventListener('change', function () {
    toggleAll();
  });

  // Event: clear completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // Event: filter links
  filterLinks.forEach(function (link) {
    link.addEventListener('click', function () {
      render();
    });
  });

  // Listen for hash changes
  window.addEventListener('hashchange', render);

  // Initial render
  render();
})();

{
  "name": "todomvc-shakedown",
  "version": "0.1.0",
  "private": true,
  "scripts": { "test": "cucumber-js" },
  "devDependencies": { "@cucumber/cucumber": "*", "happy-dom": "*" }
}

const { Given, When, Then } = require('@cucumber/cucumber');
const assert = require('assert');
const fs = require('fs');
const path = require('path');

// --- Given steps ---

Given('I open the TodoMVC app with no todos', function () {
  this.setupDom();
});

Given('I open the TodoMVC app', function () {
  this.setupDom();
});

Given('I have a todo {string}', function (title) {
  this.setupDom();
  this.addTodo(title);
});

Given('I have todos {string} and {string}', function (title1, title2) {
  this.setupDom();
  this.addTodo(title1);
  this.addTodo(title2);
});

Given('I am editing todo {string}', function (title) {
  this.editTodo(title);
});

Given('no watchbill.json file exists at the project root', function () {
  const watchbillPath = path.resolve(__dirname, '../../watchbill.json');
  assert.ok(!fs.existsSync(watchbillPath), 'watchbill.json should not exist');
});

Given('the implementation directories contain no PERTURBATION token', function () {
  const implDir = path.resolve(__dirname, '../../js');
  const files = fs.readdirSync(implDir);
  for (const file of files) {
    const content = fs.readFileSync(path.join(implDir, file), 'utf8');
    assert.ok(!content.includes('PERTURBATION'), `Found PERTURBATION in ${file}`);
  }
});

// --- When steps ---

When('I add a todo {string}', function (title) {
  this.addTodo(title);
});

When('I type {string} in the new todo input', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
});

When('I press Enter', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (editing) {
    const input = editing.querySelector('.edit');
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  } else {
    const input = this.document.querySelector('.new-todo');
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }
});

When('I click the checkbox for todo {string}', function (title) {
  const li = this.findTodoByTitle(title);
  const checkbox = li.querySelector('.toggle');
  checkbox.click();
});

When('I double-click the label for todo {string}', function (title) {
  const li = this.findTodoByTitle(title);
  const label = li.querySelector('.view label');
  label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
});

When('I hover over todo {string}', function (title) {
  const li = this.findTodoByTitle(title);
  li.dispatchEvent(new this.window.Event('mouseenter', { bubbles: true }));
  li.classList.add('hover');
});

When('I mark todo {string} as complete', function (title) {
  this.markTodoComplete(title);
});

When('I check the toggle-all checkbox', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  checkbox.click();
});

When('I click the clear completed button', function () {
  const btn = this.document.querySelector('.clear-completed');
  btn.click();
});

When('I clear the edit input', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  const input = editing.querySelector('.edit');
  input.value = '';
});

When('I type {string} in the edit input', function (text) {
  const editing = this.document.querySelector('.todo-list li.editing');
  const input = editing.querySelector('.edit');
  input.value = text;
});

When('I blur the edit input', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  const input = editing.querySelector('.edit');
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('I press Escape', function () {
  const editing = this.document.querySelector('.todo-list li.editing');
  if (editing) {
    const input = editing.querySelector('.edit');
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', bubbles: true }));
  }
});

When('I reload the page', function () {
  this.reload();
});

When('I navigate to {string}', function (filter) {
  this.navigateTo(filter);
});

When('the watchbill shape check runs', function () {
  const watchbillPath = path.resolve(__dirname, '../../watchbill.json');
  const exists = fs.existsSync(watchbillPath);
  this._checkResult = !exists;
});

When('the perturbation quiescence check runs', function () {
  const implDir = path.resolve(__dirname, '../../js');
  const files = fs.readdirSync(implDir);
  let clean = true;
  for (const file of files) {
    const content = fs.readFileSync(path.join(implDir, file), 'utf8');
    if (content.includes('PERTURBATION')) {
      clean = false;
      break;
    }
  }
  this._checkResult = clean;
});

// --- Then steps ---

Then('the {string} section is hidden', function (section) {
  const el = this.document.querySelector('.' + section);
  assert.strictEqual(el.style.display, 'none', `${section} should be hidden`);
});

Then('the {string} section is visible', function (section) {
  const el = this.document.querySelector('.' + section);
  assert.notStrictEqual(el.style.display, 'none', `${section} should be visible`);
});

Then('the counter shows {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  assert.strictEqual(counter.textContent, text);
});

Then('the counter number is wrapped in a strong tag', function () {
  const strong = this.document.querySelector('.todo-count strong');
  assert.ok(strong, 'Counter number should be in a strong tag');
});

Then('a todo {string} exists in the list', function (title) {
  const li = this.findTodoByTitle(title);
  assert.ok(li, `Todo "${title}" should exist`);
});

Then('todo {string} exists in the list', function (title) {
  const li = this.findTodoByTitle(title);
  assert.ok(li, `Todo "${title}" should exist`);
});

Then('todo {string} does not exist', function (title) {
  const li = this.findTodoByTitle(title);
  assert.ok(!li, `Todo "${title}" should not exist`);
});

Then('no todos exist in the list', function () {
  const items = this.getTodoItems();
  assert.strictEqual(items.length, 0, 'No todos should exist');
});

Then('todo {string} has class {string}', function (title, className) {
  const li = this.findTodoByTitle(title);
  assert.ok(li, `Todo "${title}" should exist`);
  assert.ok(li.classList.contains(className), `Todo "${title}" should have class "${className}"`);
});

Then('todo {string} does not have class {string}', function (title, className) {
  const li = this.findTodoByTitle(title);
  assert.ok(li, `Todo "${title}" should exist`);
  assert.ok(!li.classList.contains(className), `Todo "${title}" should not have class "${className}"`);
});

Then('todo {string} is visible', function (title) {
  const li = this.findTodoByTitle(title);
  assert.ok(li, `Todo "${title}" should exist`);
  assert.notStrictEqual(li.style.display, 'none', `Todo "${title}" should be visible`);
});

Then('todo {string} is not visible', function (title) {
  const li = this.findTodoByTitle(title);
  assert.ok(!li, `Todo "${title}" should not be visible`);
});

Then('the new todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  assert.ok(this.document.activeElement === input, 'New todo input should be focused');
});

Then('the new todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  assert.strictEqual(input.value, '', 'New todo input should be empty');
});

Then('all todos are marked complete', function () {
  const items = this.getTodoItems();
  items.forEach(li => {
    assert.ok(li.classList.contains('completed'), 'All todos should be marked complete');
  });
});

Then('the clear completed button is hidden', function () {
  const btn = this.document.querySelector('.clear-completed');
  assert.strictEqual(btn.style.display, 'none', 'Clear completed button should be hidden');
});

Then('the toggle-all checkbox is unchecked', function () {
  const checkbox = this.document.querySelector('.toggle-all');
  assert.strictEqual(checkbox.checked, false, 'Toggle-all should be unchecked');
});

Then('the {string} filter link has class {string}', function (filterName, className) {
  const links = this.document.querySelectorAll('.filters a');
  let found = null;
  links.forEach(link => {
    if (link.textContent === filterName) found = link;
  });
  assert.ok(found, `Filter link "${filterName}" should exist`);
  assert.ok(found.classList.contains(className), `Filter link "${filterName}" should have class "${className}"`);
});

Then('the edit input for todo {string} is focused', function (title) {
  const li = this.findTodoByTitle(title);
  const editInput = li.querySelector('.edit');
  assert.ok(this.document.activeElement === editInput, 'Edit input should be focused');
});

Then('the destroy button for todo {string} is visible', function (title) {
  const li = this.findTodoByTitle(title);
  const destroyBtn = li.querySelector('.destroy');
  assert.ok(destroyBtn, 'Destroy button should exist');
});

Then('the check passes', function () {
  assert.strictEqual(this._checkResult, true, 'Check should pass');
});

// --- Root index.html steps ---

Given('the root index.html exists at the project root', function () {
  const rootPath = path.resolve(__dirname, '../../index.html');
  assert.ok(fs.existsSync(rootPath), 'index.html must exist at the project root');
  this._rootHtml = fs.readFileSync(rootPath, 'utf8');
});

Then('the root index.html contains a script tag loading {string}', function (src) {
  assert.ok(this._rootHtml, 'Root index.html must be loaded');
  const pattern = new RegExp('<script[^>]+src=["\']' + src.replace('/', '\/') + '["\']');
  assert.ok(pattern.test(this._rootHtml), 'Root index.html must contain a script tag loading ' + src);
});

Then('the root index.html contains the section with class {string}', function (className) {
  assert.ok(this._rootHtml, 'Root index.html must be loaded');
  const pattern = new RegExp('<section[^>]+class=["\'][^"]*' + className + '[^"]*["\']');
  assert.ok(pattern.test(this._rootHtml), 'Root index.html must contain a section with class ' + className);
});

Then('the root index.html contains an input with class {string}', function (className) {
  assert.ok(this._rootHtml, 'Root index.html must be loaded');
  const pattern = new RegExp('<input[^>]+class=["\'][^"]*' + className + '[^"]*["\']');
  assert.ok(pattern.test(this._rootHtml), 'Root index.html must contain an input with class ' + className);
});

Then('the root index.html contains a ul with class {string}', function (className) {
  assert.ok(this._rootHtml, 'Root index.html must be loaded');
  const pattern = new RegExp('<ul[^>]+class=["\'][^"]*' + className + '[^"]*["\']');
  assert.ok(pattern.test(this._rootHtml), 'Root index.html must contain a ul with class ' + className);
});

const { World, setWorldConstructor } = require('@cucumber/cucumber');
const { Window } = require('happy-dom');
const fs = require('fs');
const path = require('path');

class TodoWorld extends World {
  constructor(options) {
    super(options);
    this.window = null;
    this.document = null;
  }

  setupDom() {
    this.window = new Window({ url: 'http://localhost/' });
    this.document = this.window.document;
    const htmlPath = path.resolve(__dirname, '../../index.html');
    const html = fs.readFileSync(htmlPath, 'utf8');
    const bodyMatch = html.match(/<body>([\s\S]*)<\/body>/);
    this.document.body.innerHTML = bodyMatch[1];
    const scriptPath = path.resolve(__dirname, '../../js/app.js');
    const script = fs.readFileSync(scriptPath, 'utf8');
    this.window.eval(script);
    this.window.localStorage.clear();
  }

  getTodoItems() {
    return Array.from(this.document.querySelectorAll('.todo-list li'));
  }

  findTodoByTitle(title) {
    return this.getTodoItems().find(li => {
      const label = li.querySelector('.view label');
      return label && label.textContent === title;
    });
  }

  addTodo(title) {
    if (!this.window) this.setupDom();
    const input = this.document.querySelector('.new-todo');
    input.value = title;
    input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', bubbles: true }));
  }

  markTodoComplete(title) {
    const li = this.findTodoByTitle(title);
    if (li) {
      const checkbox = li.querySelector('.toggle');
      if (!checkbox.checked) {
        checkbox.click();
      }
    }
  }

  editTodo(title) {
    const li = this.findTodoByTitle(title);
    if (li) {
      const label = li.querySelector('.view label');
      label.dispatchEvent(new this.window.Event('dblclick', { bubbles: true }));
    }
  }

  navigateTo(filter) {
    if (!this.window) this.setupDom();
    this.window.location.hash = filter;
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }

  reload() {
    const stored = this.window.localStorage.getItem('todomvc-shakedown');
    const hash = this.window.location.hash;
    this.setupDom();
    if (stored) {
      this.window.localStorage.setItem('todomvc-shakedown', stored);
    }
    if (hash) {
      this.window.location.hash = hash;
    }
    this.window.dispatchEvent(new this.window.Event('hashchange'));
  }
}

